}









function NewPropertyModal({
  propertyName, setPropertyName,
  propertyLocation, setPropertyLocation,
  propertyPrice, setPropertyPrice,
  propertyType, setPropertyType,
  propertyStatus, setPropertyStatus,
  propertyArea, setPropertyArea,
  propertyRooms, setPropertyRooms,
  propertyBathrooms, setPropertyBathrooms,
  propertyAvailability, setPropertyAvailability,
  propertyOwnerName, setPropertyOwnerName,
  propertyOwnerPhone, setPropertyOwnerPhone,
  propertyImageUrl, setPropertyImageUrl,
  handleAddProperty, handleUpdateProperty,
  editingProperty
}) {
  const handleSubmit = () => {
    if (editingProperty) {
      handleUpdateProperty();
    } else {
      handleAddProperty();
    }
    // Close modal manually if not using data-bs-dismiss on the button
    const modalElement = document.getElementById('newPropertyModal');
    const modal = bootstrap.Modal.getInstance(modalElement);
    if (modal) modal.hide();
  };

  return (
    <div className="modal fade" id="newPropertyModal" tabIndex="-1" aria-labelledby="newPropertyModalLabel" aria-hidden="true">
      <div className="modal-dialog">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title" id="newPropertyModalLabel">{editingProperty ? 'تعديل عقار' : 'إضافة عقار جديد'}</h5>
            <button type="button" className="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div className="modal-body">
            <form>
              <div className="mb-3">
                <label htmlFor="propertyName" className="form-label">الوصف/الاسم</label>
                <input type="text" className="form-control" id="propertyName" value={propertyName} onChange={e => setPropertyName(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyLocation" className="form-label">المدينة/المنطقة</label>
                <input type="text" className="form-control" id="propertyLocation" value={propertyLocation} onChange={e => setPropertyLocation(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyPrice" className="form-label">السعر</label>
                <input type="number" className="form-control" id="propertyPrice" value={propertyPrice} onChange={e => setPropertyPrice(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyType" className="form-label">النوع</label>
                <select className="form-select" id="propertyType" value={propertyType} onChange={e => setPropertyType(e.target.value)}>
                  <option value="">اختر النوع</option>
                  <option value="شقة">شقة</option>
                  <option value="فيلا">فيلا</option>
                  <option value="مكتب">مكتب</option>
                  <option value="محل">محل</option>
                </select>
              </div>
              <div className="mb-3">
                <label htmlFor="propertyStatus" className="form-label">الحالة</label>
                <select className="form-select" id="propertyStatus" value={propertyStatus} onChange={e => setPropertyStatus(e.target.value)}>
                  <option value="">اختر الحالة</option>
                  <option value="للبيع">للبيع</option>
                  <option value="للإيجار">للإيجار</option>
                </select>
              </div>
              <div className="mb-3">
                <label htmlFor="propertyArea" className="form-label">المساحة (م²)</label>
                <input type="number" className="form-control" id="propertyArea" value={propertyArea} onChange={e => setPropertyArea(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyRooms" className="form-label">عدد الغرف</label>
                <input type="number" className="form-control" id="propertyRooms" value={propertyRooms} onChange={e => setPropertyRooms(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyBathrooms" className="form-label">عدد الحمامات</label>
                <input type="number" className="form-control" id="propertyBathrooms" value={propertyBathrooms} onChange={e => setPropertyBathrooms(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyAvailability" className="form-label">التوفر</label>
                <select className="form-select" id="propertyAvailability" value={propertyAvailability} onChange={e => setPropertyAvailability(e.target.value)}>
                  <option value="متاحة">متاحة</option>
                  <option value="محجوزة">محجوزة</option>
                </select>
              </div>
              <div className="mb-3">
                <label htmlFor="propertyOwnerName" className="form-label">اسم المالك</label>
                <input type="text" className="form-control" id="propertyOwnerName" value={propertyOwnerName} onChange={e => setPropertyOwnerName(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyOwnerPhone" className="form-label">رقم هاتف المالك</label>
                <input type="text" className="form-control" id="propertyOwnerPhone" value={propertyOwnerPhone} onChange={e => setPropertyOwnerPhone(e.target.value)} />
              </div>
              <div className="mb-3">
                <label htmlFor="propertyImageUrl" className="form-label">رابط الصورة</label>
                <input type="text" className="form-control" id="propertyImageUrl" value={propertyImageUrl} onChange={e => setPropertyImageUrl(e.target.value)} />
              </div>
            </form>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" data-bs-dismiss="modal">إلغاء</button>
